CREATE DATABASE IF NOT EXISTS jlb_collections CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE jlb_collections;

CREATE TABLE IF NOT EXISTS users (
 id INT AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(120) NOT NULL DEFAULT '',
 email VARCHAR(190) NOT NULL UNIQUE,
 password_hash VARCHAR(255) NOT NULL,
 role ENUM('customer','admin') NOT NULL DEFAULT 'customer',
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS products (
 id INT AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(180) NOT NULL,
 category VARCHAR(60) NOT NULL,
 description TEXT,
 price DECIMAL(10,2) NOT NULL DEFAULT 0,
 stock INT NOT NULL DEFAULT 0,
 image_url TEXT,
 colors VARCHAR(255) DEFAULT 'Black,White,Brown,Green,Beige',
 sizes VARCHAR(100) DEFAULT 'S,M,L,XL,XXL',
 is_active TINYINT(1) NOT NULL DEFAULT 1,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS orders (
 id INT AUTO_INCREMENT PRIMARY KEY,
 user_id INT NOT NULL,
 total DECIMAL(10,2) NOT NULL,
 payment_method ENUM('GCash','Maya','Cash on Delivery') NOT NULL,
 address TEXT NOT NULL,
 status ENUM('Pending','Confirmed','Preparing','Shipped','Out for Delivery','Delivered','Cancelled') DEFAULT 'Pending',
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS order_items (
 id INT AUTO_INCREMENT PRIMARY KEY,
 order_id INT NOT NULL,
 product_id INT NOT NULL,
 product_name VARCHAR(180) NOT NULL,
 quantity INT NOT NULL,
 unit_price DECIMAL(10,2) NOT NULL,
 chosen_size VARCHAR(10),
 chosen_color VARCHAR(40),
 custom_design TEXT,
 FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,
 FOREIGN KEY (product_id) REFERENCES products(id)
);

CREATE TABLE IF NOT EXISTS messages (
 id INT AUTO_INCREMENT PRIMARY KEY,
 user_id INT NOT NULL,
 sender_role ENUM('customer','admin') NOT NULL,
 message TEXT NOT NULL,
 is_read TINYINT(1) DEFAULT 0,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (user_id) REFERENCES users(id)
);



CREATE TABLE IF NOT EXISTS customer_addresses (
 id INT AUTO_INCREMENT PRIMARY KEY,
 user_id INT NOT NULL,
 recipient_name VARCHAR(120) NOT NULL,
 phone VARCHAR(30) NOT NULL,
 region VARCHAR(120) NOT NULL,
 province VARCHAR(120) NOT NULL,
 city VARCHAR(120) NOT NULL,
 barangay VARCHAR(120) NOT NULL,
 street VARCHAR(180) NOT NULL,
 postal_code VARCHAR(12) NOT NULL,
 landmark VARCHAR(180) DEFAULT '',
 is_default TINYINT(1) NOT NULL DEFAULT 1,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CONSTRAINT fk_customer_addresses_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
 INDEX idx_customer_address_default (user_id, is_default)
) ENGINE=InnoDB;
